using System.Text;
using Dalamud.Game.Text.SeStringHandling;
namespace TooltipExtras;

internal static class MateriaPresentation
{
    // Keep only the stat name and the suffix generated by Simple. The old numeric
    // prefix can belong to an inactive/reused game string slot; it is not a result.
    public static byte[]? Extract(byte[] row)
    {
        var marker=row.AsSpan().LastIndexOf(" ["u8);
        if(marker<=0||row[^1]!=(byte)']')return null;
        var prefix=SeString.Parse(row.AsSpan(0,marker).ToArray()).TextValue;
        var split=prefix.LastIndexOf(" +",StringComparison.Ordinal);
        if(split<=0||split+2>=prefix.Length)return null;
        foreach(var c in prefix.AsSpan(split+2))if(c is < '0' or > '9')return null;
        return [..Encoding.UTF8.GetBytes(prefix[..split]),..row.AsSpan(marker).ToArray()];
    }
}
